/**
 * @name Unsafe deserialization in ASN.1 parser
 * @description ASN.1 parsers can be vulnerable to code injection or unsafe deserialization
 * @kind path-problem
 * @problem.severity error
 * @id py/unsafe-deserialization
 * @tags security
 *        external/cwe/cwe-502
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module DeserializationConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(CodeExecution ce |
      sink = ce.getCode()
    )
  }
}

module DeserializationFlow = TaintTracking::Global<DeserializationConfig>;
import DeserializationFlow::PathGraph

from DeserializationFlow::PathNode source, DeserializationFlow::PathNode sink
where DeserializationFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "ASN.1 deserialization operation that could be vulnerable to code injection $@.", source.getNode(), "user input"

/**
 * @name File operation with untrusted input
 * @description File operations with untrusted input could lead to path traversal or denial of service
 * @kind path-problem
 * @problem.severity error
 * @id py/file-operation
 * @tags security
 *        external/cwe/cwe-22
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module FileOperationConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(FileSystemAccess fa |
      sink = fa.getAPathArgument()
    )
  }
}

module FileOperationFlow = TaintTracking::Global<FileOperationConfig>;
import FileOperationFlow::PathGraph

from FileOperationFlow::PathNode source, FileOperationFlow::PathNode sink
where FileOperationFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "File operation with untrusted input $@.", source.getNode(), "user input"

